import{_ as t,o as n,c as a,a5 as o}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"3.4.1 List Agency","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-1-list-agency/spec.md","filePath":"feature/agency-workspace/3-4-1-list-agency/spec.md"}'),i={name:"feature/agency-workspace/3-4-1-list-agency/spec.md"};function s(r,e,l,c,h,u){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="_3-4-1-list-agency" tabindex="-1">3.4.1 List Agency <a class="header-anchor" href="#_3-4-1-list-agency" aria-label="Permalink to &quot;3.4.1 List Agency&quot;">​</a></h1><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>The user navigates to the Agencies page (<code>/agencies</code>) after signing in. This is the default landing page when the user already owns or belongs to at least one Agency.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Signed-in user (Agency Owner or Agency Member).</li><li><strong>Purpose:</strong> Present every Agency the current user owns or belongs to, so the user can pick one to manage.</li><li><strong>Interface:</strong> Agencies page (<code>/agencies</code>) — a grid of Agency cards showing name, logo and category, plus an empty state with a &quot;Create new Agency&quot; call to action when the user owns or belongs to no Agency.</li><li><strong>Data Processing:</strong> The system merges the Agencies where the user is the Owner with the Agencies where the user holds an Agency Member record, de-duplicates the two sources, excludes soft-deleted Agencies, and returns the combined list together with the full profile of each Agency.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Agencies page:</p><ul><li>A card per Agency, each showing name, logo and category.</li><li>Selecting a card moves the user into that Agency. The Agency Dashboard (3.4.2) has no screen of its own yet, so the Agency Profile (3.4.4) is shown in the meantime.</li><li>Empty state with a &quot;Create new Agency&quot; call to action when the user owns or belongs to no Agency.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> None — the request carries no parameters and no filters.</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> Agency profile — id (UUID), name, ownerId (UUID), logoUrl, description, category (AgencyCategory: MARKETING, FNB, FASHION, BEAUTY, TECHNOLOGY, REAL_ESTATE, EDUCATION, HEALTHCARE, RETAIL, FINANCE, ENTERTAINMENT, OTHER), companySize (CompanySize: SIZE_1_10, SIZE_11_50, SIZE_51_200, SIZE_201_500, SIZE_500_PLUS), website, phone, location, brandColor, logoIcon, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, status (EntityStatus: ACTIVE / SOFT_DELETED), createdAt, updatedAt.</li><li><strong>Output:</strong> The list of Agencies that match the current user, each with the full profile above; an empty list when the user owns or belongs to none.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-29:</strong> Multi-tenancy — the list is scoped to the current user: the Agencies where the user is the Owner, plus the Agencies where the user holds an Agency Member record (whatever the role). A user with no active membership or ownership sees nothing beyond that scope.</li><li>Agencies whose status is SOFT_DELETED are left out of the list.</li><li>The result carries no pre-computed workspace count.</li><li>Selecting an Agency leads to the Agency Dashboard (3.4.2). That screen has no data source of its own yet, so the Agency Profile (3.4.4) stands in until it is built.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>None — the operation returns a list for every signed-in user, including an empty one.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The user opens the Agencies page.</li><li>The client requests the Agency list of the signed-in user.</li><li>The system gathers the Agencies owned by the user and the Agencies where the user holds a membership, merges and de-duplicates both sources, drops soft-deleted entries, and returns the result.</li><li>The client renders one card per Agency, showing name, logo and category.</li><li>The user selects a card to move into that Agency.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>The user owns and belongs to no Agency: an empty list is returned rather than an error, and the client shows the empty state with the &quot;Create new Agency&quot; call to action.</li><li>No signed-in session: the request is rejected with <code>401 UNAUTHORIZED</code> before any Agency logic runs.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The list reflects exactly the Agencies the current user owns or belongs to, with soft-deleted Agencies excluded.</li><li>No Agency data is created, changed or removed.</li></ul>',22)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
